-- 00-preview-before-apply：套用 ga-improve-b1 之前的只讀預覽（只有 SELECT）。確認先決條件（G46 水電請款已套用）、現有資料量、設定鍵、約束現況、各被加掛函式的現行定義雜湊、permissions 欄位與含舊名稱的列。
-- 套用完成後可再跑一次對照。雜湊用來確認「正式區函式與 DEV 實測時是否相同」：不同代表函式有差異，加掛會依形狀檢查，不符就中止。
SELECT '先決：G46 水電請款已套用（ga_payment_request_bill_lines 存在）' AS item, CASE WHEN to_regclass('public.ga_payment_request_bill_lines') IS NOT NULL THEN 'ok' ELSE 'MISSING：請先套用 ga-utility-payment-sql 01 至 04' END AS value
UNION ALL SELECT '先決：第 4.5 批請款單函式', CASE WHEN to_regprocedure('public.ga_pay_request_json(uuid,boolean,boolean,boolean)') IS NOT NULL THEN 'ok' ELSE 'MISSING' END
UNION ALL SELECT '先決：採購單與進貨表', CASE WHEN to_regclass('public.ga_purchase_orders') IS NOT NULL AND to_regclass('public.ga_purchase_receipt_items') IS NOT NULL THEN 'ok' ELSE 'MISSING' END
UNION ALL SELECT '已套用 ga-improve-b1（買受人公司表存在）', CASE WHEN to_regclass('public.ga_buyer_companies') IS NOT NULL THEN 'yes（重複套用安全，會略過已套用的部分）' ELSE 'no' END
UNION ALL SELECT '採購單筆數', (SELECT count(*)::text FROM public.ga_purchase_orders)
UNION ALL SELECT '進貨單筆數（未作廢／全部）', (SELECT count(*) FILTER (WHERE voided_at IS NULL)::text || ' / ' || count(*)::text FROM public.ga_purchase_receipts)
UNION ALL SELECT '請款單筆數（草稿／已送出／已付款／作廢）', (SELECT count(*) FILTER (WHERE status = 'DRAFT')::text || ' / ' || count(*) FILTER (WHERE status = 'SUBMITTED')::text || ' / ' || count(*) FILTER (WHERE status = 'PAID')::text || ' / ' || count(*) FILTER (WHERE status = 'VOID')::text FROM public.ga_payment_requests)
UNION ALL SELECT '設定鍵 pay_buyer_title', COALESCE((SELECT COALESCE(value_text, '（空）') FROM public.ga_workflow_settings WHERE key = 'pay_buyer_title'), '（沒有這個鍵）')
UNION ALL SELECT '設定鍵 pay_buyer_tax_id', COALESCE((SELECT COALESCE(value_text, '（空）') FROM public.ga_workflow_settings WHERE key = 'pay_buyer_tax_id'), '（沒有這個鍵）')
UNION ALL SELECT '買受人設定能否搬成預設公司（兩個值都有且統編 8 碼）', CASE WHEN EXISTS (SELECT 1 FROM public.ga_workflow_settings WHERE key = 'pay_buyer_tax_id' AND btrim(value_text) ~ '^[0-9]{8}$') AND EXISTS (SELECT 1 FROM public.ga_workflow_settings WHERE key = 'pay_buyer_title' AND btrim(COALESCE(value_text, '')) <> '') THEN '可以搬' ELSE '不搬（由總務補齊後手動新增公司）' END
UNION ALL SELECT '付款方式約束現況', COALESCE((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'ga_payment_requests_pay_method_check'), '（沒有）')
UNION ALL SELECT '請款事件類型約束現況', COALESCE((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'ga_payment_request_events_type_check'), '（沒有）')
UNION ALL SELECT 'permissions 欄位', (SELECT string_agg(column_name, '、' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'permissions')
UNION ALL SELECT 'permissions 含舊名稱「水電網費管理」的列數', (SELECT count(*)::text FROM public.permissions p WHERE to_jsonb(p)::text LIKE '%水電網費管理%')
UNION ALL SELECT '函式本體含舊名稱「水電網費管理」的函式數', (SELECT count(*)::text FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.prokind = 'f' AND position('水電網費管理' IN p.prosrc) > 0)
UNION ALL SELECT '函式定義雜湊 ' || x.sig, COALESCE(md5(pg_get_functiondef(to_regprocedure(x.sig))), '（函式不存在）') FROM unnest(ARRAY['public.ga_pay_apply_lines(uuid,uuid,jsonb)', 'public.ga_pay_check_live(uuid)', 'public.ga_pay_check_tol_reasons(uuid)', 'public.ga_pay_freeze_receipt_item_amount()', 'public.ga_pay_po_amounts(uuid[])', 'public.ga_pay_po_claimed(uuid,uuid,text)', 'public.ga_pay_po_received(uuid)', 'public.ga_pay_receipt_total(uuid)', 'public.ga_pay_receipt_untaxed(uuid)', 'public.ga_pay_request_json(uuid,boolean,boolean,boolean)', 'public.ga_pay_unclaimed_po_ids(numeric)', 'public.ga_po_data(uuid)', 'public.ga_po_header_apply(uuid,jsonb)', 'public.ga_po_items_apply(uuid,jsonb)', 'public.ga_po_receipt_data(uuid)', 'public.ga_po_refresh_totals(uuid)', 'public.ga_ws_home_summary()', 'public.ga_ws_pay_export(jsonb)', 'public.ga_ws_pay_invoice_save(uuid,jsonb,text,timestamp with time zone)', 'public.ga_ws_pay_po_summary(uuid)', 'public.ga_ws_pay_receipt_candidates(jsonb,integer,integer)', 'public.ga_ws_pay_request_action(uuid,text,jsonb,text,timestamp with time zone)', 'public.ga_ws_pay_request_create(jsonb,text)', 'public.ga_ws_pay_request_get(uuid)', 'public.ga_ws_pay_request_list(jsonb,integer,integer)', 'public.ga_ws_pay_request_update(uuid,jsonb,timestamp with time zone)', 'public.ga_ws_pay_settings_get()', 'public.ga_ws_pay_settings_set(jsonb,timestamp with time zone)', 'public.ga_ws_pay_ub_create(jsonb,text)', 'public.ga_ws_pay_ub_update(uuid,jsonb,timestamp with time zone)', 'public.ga_ws_po_action(uuid,text,timestamp with time zone,text)', 'public.ga_ws_po_list(jsonb,integer,integer)', 'public.ga_ws_po_receipt_void(uuid,uuid,text,text,timestamp with time zone)', 'public.ga_ws_po_receive(uuid,jsonb,jsonb,text)']) AS x(sig)
UNION ALL SELECT '權限語意：has_permission 定義雜湊', COALESCE((SELECT md5(pg_get_functiondef(p.oid)) FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'has_permission' LIMIT 1), '（沒有）');
